/** Reference epoch for distances quoted in cards (the BigRed//Hacks demo day). */
export const REFERENCE_EPOCH = "2026-10-04";

export interface SolarBody {
  id: string;
  name: string;
  aliases?: string[];
  type: "star" | "planet" | "dwarf-planet" | "moon" | "asteroid" | "comet" | "spacecraft";
  horizons: string;
  /** Parent ephemeris key for moons (elements are fetched relative to it). */
  parent?: string;
  factsheet?: string;
  wiki?: string;
  texture?: string;
  color: string;
  priority: number;
  /** IAU WGCCRE (Archinal et al. 2018) pole RA/Dec, J2000, used only to orient textures. */
  pole?: { ra: number; dec: number };
  rings?: { innerKm: number; outerKm: number; texture?: string };
  /** Fallback radius when neither the NASA fact sheet nor Horizons provides one. */
  subtitle: string;
}

