export type DistanceSpec =
  | { kind: "parallax" }
  | { kind: "simbad"; bibcode: string }
  | { kind: "literature"; valuePc: number; plusPc?: number; minusPc?: number; bibcode: string; citation: string; quality: "precise" | "good" | "approximate" | "uncertain"; note?: string };

export interface CuratedObject {
  id: string;
  name: string;
  aliases?: string[];
  simbad: string;
  type: "star" | "star-cluster" | "nebula" | "galaxy" | "black-hole" | "quasar";
  region: "stellar-neighborhood" | "milky-way" | "local-group" | "local-volume" | "cosmological";
  wiki: string;
  distance: DistanceSpec | { kind: "none"; reason: string };
  priority: number;
  subtitle?: string;
  exoplanetHost?: string;
  /** Wikimedia Commons file to use instead of the article lead image, or null for none. */
  image?: string | null;
  imageKind?: "observed" | "illustration";
}

